validation.command:
node --input-type=module - <<'NODE'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
const root='research/discovery-sprint-2026-10-05/';
const read=p=>JSON.parse(fs.readFileSync(root+p,'utf8'));
const compounds=read('emergence/raw/stream-c.json').compounds;
for(const name of ['M101','M105']){
 const c=read('prior_art_court/emergence/'+name+'.json');
 assert.equal(c.id,'E4:'+name);
 assert.equal(c.exact_proposition,compounds.find(x=>x.id===c.id).surprising_prediction);
 assert(c.nearest_primary_works.length>=5);
 for(const w of c.nearest_primary_works){
  assert.equal(w.primary,true);assert(w.url.startsWith('https://'));assert(w.exact_paraphrased_proposition);assert(w.inspection.read&&w.inspection.limit);
  for(const k of ['same_variables','same_full_causal_graph','same_beneficiary','same_outcome','same_timescale','same_distinguishing_prediction','same_intervention'])assert(w.comparison[k],w.id+' '+k);
 }
 for(const k of ['strongest_defensible_version','extra_assumptions_added','KNOWN','NEW_RESIDUE','expert_already_knowing_strongest_prior_art','minimum_distinguishing_experiment','beneficial_mirror','strongest_falsifier','further_mutation','provisional_remainder_class'])assert(c[k],name+' '+k);
 assert(fs.readFileSync(root+'prior_art_court/emergence/'+name+'.md','utf8').length>2000);
}
const log=read('prior_art_court/emergence/query-log-c-M101-M105.json');
assert.equal(log.queries.length,18);assert.equal(log.inspected_primary_documents.length,11);
for(const file of read('emergence/pause-snapshot.json').files){
 const hash=crypto.createHash('sha256').update(fs.readFileSync(root+file.path)).digest('hex');
 assert.equal(hash,file.sha256,'Paused input changed '+file.path);
}
console.log(JSON.stringify({records:2,primary_works:[6,5],per_work_comparison_fields:7,actual_queries:18,paused_hashes_verified:6,canonical_population_mutations:0,blind_panel:false,novelty_certified:false}));
NODE
